typedef float rational_t;
#define DEG_TO_RAD(a) ((a) * (3.14159265358979323846f / 180.0f))

struct vector3d
{
	float x;
	float y;
	float z;
	float w;
};

extern const vector3d YVEC;

class po
{
public:
	float m[4][4];

	void set_rot(const vector3d& rot_dir, float rads);
	po operator*(const po& b) const;
};

class PhysicsObjectClass
{
public:
	char reserved[48];
	po my_po;
};

typedef PhysicsObjectClass *PhysicsObjectClassPtr;

class SurfBoardObjectClass
{
public:
	char reserved0[4];
	PhysicsObjectClassPtr rb;
	char reserved1[2588];
	int wiped_out;

	void TrickSpin(float angle);
};

void SurfBoardObjectClass::TrickSpin(float angle)
{
	if (!wiped_out)
	{
		po turn;
		turn.set_rot (YVEC, DEG_TO_RAD((angle)));
		rb->my_po = (turn * rb->my_po);
	}
}
